# ─────────── среда выполнения bit (x86_64) ───────────
# аргументы: rdi, rsi, rdx, rcx, r8, r9; результат: rax
.p2align 4
_bit_signal_handler:                 # async-signal-safe: set one aligned flag
    mov dword ptr [rip + Lrt_signalled], 1
    ret

_bit_signalled:
    xor eax, eax
    cmp dword ptr [rip + Lrt_signalled], 0
    setne al
    ret

_bit_signal_init:                    # Linux/glibc sigaction with SA_RESTART
    push rbp
    mov rbp, rsp
    sub rsp, 160
    mov rdi, rsp
    xor esi, esi
    mov edx, 152
    call memset@PLT
    lea rax, [rip + _bit_signal_handler]
    mov [rsp], rax
    mov dword ptr [rsp + 136], 0x10000000
    mov edi, 2                       # SIGINT
    mov rsi, rsp
    xor edx, edx
    call sigaction@PLT
    test eax, eax
    jnz 9f
    mov edi, 15                      # SIGTERM
    mov rsi, rsp
    xor edx, edx
    call sigaction@PLT
    test eax, eax
    jnz 9f
    add rsp, 160
    pop rbp
    ret
9:  add rsp, 160
    pop rbp
    lea rdi, [rip + Lrt_esignal]
    xor esi, esi
    jmp _bit_die

_bit_rt_ensure:                     # однократная подготовка ключа потока и замка строк
    cmp byte ptr [rip + Lrt_ready], 0
    jne 9f
    push rbp
    mov rbp, rsp
    sub rsp, 16
    lea rdi, [rip + Lrt_tkey]
    xor esi, esi
    call pthread_key_create@PLT
    lea rdi, [rip + Lrt_slock]
    xor esi, esi
    call pthread_mutex_init@PLT
    mov byte ptr [rip + Lrt_ready], 1
    add rsp, 16
    pop rbp
