_bit_lock:
    push rbp
    mov rbp, rsp
    call _bit_rt_ensure
    lea rdi, [rip + Lrt_slock]
    call pthread_mutex_lock@PLT
    pop rbp
    ret

_bit_unlock:
    push rbp
    mov rbp, rsp
    lea rdi, [rip + Lrt_slock]
    call pthread_mutex_unlock@PLT
    pop rbp
    ret

_bit_tstate:                        # → блок состояния этого потока
    push rbp
    mov rbp, rsp
    push rbx
    sub rsp, 8
    call _bit_rt_ensure
    mov rdi, [rip + Lrt_tkey]
    call pthread_getspecific@PLT
    test rax, rax
    jnz 9f
    mov edi, 64
    call _bit_alloc
    mov rbx, rax
    mov rdi, rax
    xor esi, esi
    mov edx, 64
    call memset@PLT
    mov rdi, [rip + Lrt_tkey]
    mov rsi, rbx
    call pthread_setspecific@PLT
    mov rax, rbx
9:  add rsp, 8
    pop rbx
    pop rbp
    ret

_bit_recover_enter:                 # rdi = frame allocated by the compiler
    push rbp
    mov rbp, rsp
    push rbx
    push r12
    mov r12, rdi
    call _bit_tstate
    mov rbx, rax
    mov rax, [rbx]
    mov [r12 + 168], rax
    mov [rbx], r12
    mov rax, [rbx + 8]
    mov [r12 + 176], rax
    mov qword ptr [rbx + 32], 0
    mov rax, r12
    pop r12
    pop rbx
    pop rbp
    ret

_bit_recover_leave:
    push rbp
    mov rbp, rsp
    push rbx
    sub rsp, 8
    call _bit_tstate
    mov rbx, rax
    mov rax, [rbx]
    mov rax, [rax + 168]
    mov [rbx], rax
    add rsp, 8
    pop rbx
    pop rbp
    ret

_bit_own_str:                       # rdi = stack record with string and previous pointer
    push rbp
    mov rbp, rsp
    push rbx
    sub rsp, 8
    mov rbx, rdi
    call _bit_tstate
    mov rcx, [rax + 8]
    mov [rbx + 8], rcx
    mov [rax + 8], rbx
    add rsp, 8
    pop rbx
    pop rbp
    ret

_bit_drop_owned:
    push rbp
    mov rbp, rsp
    push rbx
    sub rsp, 8
    call _bit_tstate
    mov rbx, rax
    mov rax, [rbx + 8]
    mov rcx, [rax + 8]
    mov [rbx + 8], rcx
    mov rdi, [rax]
    add rsp, 8
    pop rbx
    pop rbp
    jmp _bit_drop_str

_bit_setjmp:                        # rdi = буфер → 0; сохраняет callee-saved, sp и адрес возврата
