    mov [rdi + 8], rbp
    mov [rdi + 16], r12
    mov [rdi + 24], r13
    mov [rdi + 32], r14
    mov [rdi + 40], r15
    lea rdx, [rsp + 8]
    mov [rdi + 48], rdx
    mov rdx, [rsp]
    mov [rdi + 56], rdx
    xor eax, eax
    ret

_bit_longjmp:                       # rdi = буфер, rsi = значение → возврат из _bit_setjmp
    mov rbx, [rdi]
    mov rbp, [rdi + 8]
    mov r12, [rdi + 16]
    mov r13, [rdi + 24]
    mov r14, [rdi + 32]
    mov r15, [rdi + 40]
    mov rsp, [rdi + 48]
    mov rax, rsi
    jmp qword ptr [rdi + 56]

_bit_set_errcode:                   # rdi = код → запомнить для этого потока
    push rbp
    mov rbp, rsp
    push rbx
    sub rsp, 8
    mov rbx, rdi
    call _bit_tstate
    mov [rax + 32], rbx
    add rsp, 8
    pop rbx
    pop rbp
    ret

_bit_term_errcode:                  # → код последней пойманной ошибки (0 = без кода)
    push rbp
    mov rbp, rsp
    call _bit_tstate
    mov rax, [rax + 32]
    pop rbp
    ret

_bit_errno_map:                     # edi = код ошибки системы → 1 отказ, 2 таймаут, 3 нет маршрута, 0 без кода
    cmp edi, 111                     # ECONNREFUSED (Linux)
    je 1f
    cmp edi, 110                     # ETIMEDOUT (Linux)
    je 2f
    cmp edi, 101                     # ENETUNREACH (Linux)
    je 3f
    cmp edi, 113                     # EHOSTUNREACH (Linux)
    je 3f
    xor eax, eax
    ret
1:  mov eax, 1
    ret
2:  mov eax, 2
    ret
3:  mov eax, 3
    ret

_bit_errno_code:                    # → код ошибки системы из errno
    push rbp
    mov rbp, rsp
    call __errno_location@PLT
    mov edi, dword ptr [rax]
    pop rbp
    jmp _bit_errno_map

# User locks have process lifetime; aliases refer to the same mutex.
_bit_user_lock_new:
    push rbp
    mov rbp, rsp
    push rbx
    sub rsp, 8
    mov edi, 80
    call _bit_alloc
    mov rbx, rax
    mov rdi, rax
    xor esi, esi
    call pthread_mutex_init@PLT
    test eax, eax
    jnz 1f
    mov rax, rbx
    add rsp, 8
    pop rbx
    pop rbp
    ret
1:  mov rdi, rbx
    call free@PLT
    lea rdi, [rip + Lrt_elock]
    xor esi, esi
    add rsp, 8
    pop rbx
    pop rbp
    jmp _bit_die

_bit_user_lock_enter:                # rdi = lock, rsi = source line
    push rbp
    mov rbp, rsp
    push rbx
    sub rsp, 8
    mov rbx, rsi
    call pthread_mutex_lock@PLT
    test eax, eax
    jnz 1f
    add rsp, 8
    pop rbx
    pop rbp
    ret
1:  lea rdi, [rip + Lrt_elock]
    mov rsi, rbx
    add rsp, 8
    pop rbx
    pop rbp
    jmp _bit_die

_bit_user_lock_leave:                # rdi = lock, rsi = source line
    push rbp
    mov rbp, rsp
    push rbx
    sub rsp, 8
    mov rbx, rsi
    call pthread_mutex_unlock@PLT
    test eax, eax
    jnz 1f
    add rsp, 8
    pop rbx
    pop rbp
    ret
1:  lea rdi, [rip + Lrt_elock]
    mov rsi, rbx
    add rsp, 8
    pop rbx
    pop rbp
    jmp _bit_die

_bit_thread_start:                  # rdi = code -> stable thread token
    push rbp
    mov rbp, rsp
    push rbx
    push r12
    push r13
    push r14
    mov rbx, rdi
    # No bit thread can start before the shared registry and TLS key exist.
    call _bit_rt_ensure
    mov edi, 128
    call _bit_alloc
    mov r12, rax
    mov qword ptr [r12 + 24], 0
    mov qword ptr [r12 + 32], 0
    mov qword ptr [r12 + 120], 0
    lea rdi, [r12 + 40]
    xor esi, esi
    call pthread_cond_init@PLT
    test eax, eax
    jnz 8f
    lea rdi, [r12 + 16]
    xor esi, esi
    lea rdx, [rip + _bit_thread_run]
    mov rcx, rbx
    call pthread_create@PLT
    test eax, eax
    jnz 9f
    call _bit_lock
    mov r13, [rip + Lrt_thread_next]
    lea rax, [r13 + 1]
    mov [rip + Lrt_thread_next], rax
    mov [r12 + 8], r13
    mov rax, [rip + Lrt_thread_list]
    mov [r12], rax
    mov [rip + Lrt_thread_list], r12
    call _bit_unlock
    mov rax, r13
    pop r14
    pop r13
    pop r12
    pop rbx
    pop rbp
    ret
