    call pthread_cond_destroy@PLT
8:  mov rdi, r12
    call free@PLT
    lea rdi, [rip + Lrt_ethread]
    xor esi, esi
    pop r14
    pop r13
    pop r12
    pop rbx
    pop rbp
    jmp _bit_die

_bit_thread_run:                    # rdi = код потока
    push rbp
    mov rbp, rsp
    call rdi
    # State is optional: do not allocate it just to destroy it.
    mov rdi, [rip + Lrt_tkey]
    call pthread_getspecific@PLT
    test rax, rax
    jz 1f
    mov rdi, rax
    call free@PLT
