    xor eax, eax
    pop rbp
    ret

_bit_thread_wait:                   # rdi = stable token; completed tokens are no-ops
    push rbp
    mov rbp, rsp
    push rbx
    push r12
    push r13
    push r14
    mov rbx, rdi
    call _bit_lock
    mov r12, [rip + Lrt_thread_list]
